function e(e,t,n,r){let i=r*n,a=t-i,o=i/t,s=e*.02,c=e*.25,l=s/o,u=Math.min(l,c);return{stopPrice:a,stopDistance:i,stopPct:o,position:u,positionPct:u/e*100,posByRisk:l,maxAllowed:c}}function t(e,t,n){let r=t-e;return{reward:r,ratio:r/n}}function n(e,t){return e*(1-t)}var r={trend:{name:`趋势突破`,n:1.5,callback:.08,holdDays:`1-4周`},pullback:{name:`回调买入`,n:2,callback:.15,holdDays:`2-8周`},bottom:{name:`底部右侧确认`,n:3,callback:.2,holdDays:`1-6月`}};export{n as i,e as n,t as r,r as t};